draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // habit 1: be proactive
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/7, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '14px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Be Proactive', W/7, H/2 + 25);

  // habit 2: begin with the end
  ctx.beginPath();
  ctx.arc(2*W/7, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillText('Begin with', 2*W/7, H/2 + 25);
  ctx.fillText('the End', 2*W/7, H/2 + 40);

  // habit 3: put first things first
  ctx.beginPath();
  ctx.arc(3*W/7, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillText('Put First', 3*W/7, H/2 + 25);
  ctx.fillText('Things First', 3*W/7, H/2 + 40);

  // habit 4: think win-win
  ctx.beginPath();
  ctx.arc(4*W/7, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillText('Think Win-', 4*W/7, H/2 + 25);
  ctx.fillText('Win', 4*W/7, H/2 + 40);

  // habit 5: seek first to understand
  ctx.beginPath();
  ctx.arc(5*W/7, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillText('Seek to', 5*W/7, H/2 + 25);
  ctx.fillText('Understand', 5*W/7, H/2 + 40);

  // habit 6: synergize
  ctx.beginPath();
  ctx.arc(6*W/7, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillText('Synergize', 6*W/7, H/2 + 25);

  // habit 7: sharpen the saw
  ctx.beginPath();
  ctx.arc(W, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.save();
  ctx.translate(W, H/2);
  ctx.rotate(Math.sin(t));
  ctx.fillText('Sharpen', -20, 25);
  ctx.fillText('the Saw', -20, 40);
  ctx.restore();

  ctx.restore();
}
